   584  void AddressResolver::HandleAddressQuery(Coap::Message &aMessage, const Ip6::MessageInfo &aMessageInfo)
   585  {
   586      ThreadTargetTlv              targetTlv;
   587      ThreadMeshLocalEidTlv        mlIidTlv;
   588      ThreadLastTransactionTimeTlv lastTransactionTimeTlv;
   589
   590      VerifyOrExit(aMessage.GetType() == OT_COAP_TYPE_NON_CONFIRMABLE && aMessage.GetCode() == OT_COAP_CODE_POST);
   591
   592      SuccessOrExit(ThreadTlv::GetTlv(aMessage, ThreadTlv::kTarget, sizeof(targetTlv), targetTlv));
   593      VerifyOrExit(targetTlv.IsValid());
   594
   595      mlIidTlv.Init();
   596
   597      lastTransactionTimeTlv.Init();
   598
   599      otLogInfoArp("Received address query from 0x%04x for target %s",
   600                   HostSwap16(aMessageInfo.GetPeerAddr().mFields.m16[7]), targetTlv.GetTarget().ToString().AsCString());
   601
   602      if (Get<ThreadNetif>().IsUnicastAddress(targetTlv.GetTarget()))
   603      {
   604          mlIidTlv.SetIid(Get<Mle::MleRouter>().GetMeshLocal64().GetIid());
   605          SendAddressQueryResponse(targetTlv, mlIidTlv, NULL, aMessageInfo.GetPeerAddr());
   606          ExitNow();
   607      }
   608
   609      for (ChildTable::Iterator iter(GetInstance(), ChildTable::kInStateValid); !iter.IsDone(); iter++)
   610      {
   611          Child &child = *iter.GetChild();
   612
   613          if (child.IsFullThreadDevice() || child.GetLinkFailures() >= Mle::kFailedChildTransmissions)
   614          {
   615              continue;
   616          }
   617
   618          if (child.HasIp6Address(GetInstance(), targetTlv.GetTarget()))
   619          {
   620              mlIidTlv.SetIid(child.GetExtAddress());
   621              lastTransactionTimeTlv.SetTime(TimerMilli::Elapsed(child.GetLastHeard()));
   622              SendAddressQueryResponse(targetTlv, mlIidTlv, &lastTransactionTimeTlv, aMessageInfo.GetPeerAddr());
   623              ExitNow();
   624          }
   625      }
